insert into public.questions (id, kind, prompt, options, marks, image_url) values ('376c27b3-3755-5142-9389-05bf9ffcd6bf', 'short', 'Distinguish between the structure of arteries and veins.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('376c27b3-3755-5142-9389-05bf9ffcd6bf', 'Arteries have thicker walls than veins [1]; arteries have a narrow lumen, veins a wide lumen [1]; veins have valves, arteries do not (except at the heart) [1]; arteries have more elastic fibres and smooth muscle [1]. (Any three.)', 'Arteries have thicker walls than veins [1]; arteries have a narrow lumen, veins a wide lumen [1]; veins have valves, arteries do not (except at the heart) [1]; arteries have more elastic fibres and smooth muscle [1]. (Any three.)', '[{"text": "Marking point 1", "any": ["thicker wall", "thinner wall"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["lumen", "wider lumen"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["valve"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["elastic", "muscle"], "all": [], "marks": 1}]'::jsonb, 'Arteries have thicker walls than veins [1]; arteries have a narrow lumen, veins a wide lumen [1]; veins have valves, arteries do not (except at the heart) [1]; arteries have more elastic fibres and smooth muscle [1]. (Any three.)') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('1753b7c5-9908-5903-8e74-84bfdecea2be', '376c27b3-3755-5142-9389-05bf9ffcd6bf', 16);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('bdcda210-240b-5d43-b70f-0138647f72e9', 'short', 'Explain how water is moved up the xylem during transpiration.', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('bdcda210-240b-5d43-b70f-0138647f72e9', 'Water evaporates from mesophyll cell walls and is lost by transpiration [1]; water is drawn out of the xylem through cell walls by capillary action/adhesion to replace it [1]; this creates tension (negative pressure) in the xylem that pulls water up [1]; cohesion between water molecules (hydrogen bonds) keeps the column continuous [1].', 'Water evaporates from mesophyll cell walls and is lost by transpiration [1]; water is drawn out of the xylem through cell walls by capillary action/adhesion to replace it [1]; this creates tension (negative pressure) in the xylem that pulls water up [1]; cohesion between water molecules (hydrogen bonds) keeps the column continuous [1].', '[{"text": "Marking point 1", "any": ["evaporat", "transpiration"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["cell wall", "capillary", "adhesion", "drawn out"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["tension", "negative pressure", "pull"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["cohesion", "hydrogen bond", "continuous column"], "all": [], "marks": 1}]'::jsonb, 'Water evaporates from mesophyll cell walls and is lost by transpiration [1]; water is drawn out of the xylem through cell walls by capillary action/adhesion to replace it [1]; this creates tension (negative pressure) in the xylem that pulls water up [1]; cohesion between water molecules (hydrogen bonds) keeps the column continuous [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('1753b7c5-9908-5903-8e74-84bfdecea2be', 'bdcda210-240b-5d43-b70f-0138647f72e9', 17);
