insert into public.questions (id, kind, prompt, options, marks, image_url) values ('65becf97-660c-5c08-a1d1-bb54384df5d9', 'short', 'Distinguish between transmembrane and intracellular receptors.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Signal_Transduction_Diagram-_Insulin.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('65becf97-660c-5c08-a1d1-bb54384df5d9', 'Transmembrane receptors are in the plasma membrane; intracellular receptors are in the cytoplasm or nucleus [1]; transmembrane receptors have a region of hydrophobic amino acids within the membrane, intracellular receptors are hydrophilic on the surface [1]; ligands of transmembrane receptors stay outside the cell, while ligands of intracellular receptors (e.g. steroids) penetrate the membrane [1].', 'Transmembrane receptors are in the plasma membrane; intracellular receptors are in the cytoplasm or nucleus [1]; transmembrane receptors have a region of hydrophobic amino acids within the membrane, intracellular receptors are hydrophilic on the surface [1]; ligands of transmembrane receptors stay outside the cell, while ligands of intracellular receptors (e.g. steroids) penetrate the membrane [1].', '[{"text": "Marking point 1", "any": ["plasma membrane", "cytoplasm", "nucleus"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["hydrophobic amino acids", "hydrophobic region", "amino acids"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["outside", "enters", "penetrat", "steroid", "hydrophilic ligand", "cannot cross"], "all": [], "marks": 1}]'::jsonb, 'Transmembrane receptors are in the plasma membrane; intracellular receptors are in the cytoplasm or nucleus [1]; transmembrane receptors have a region of hydrophobic amino acids within the membrane, intracellular receptors are hydrophilic on the surface [1]; ligands of transmembrane receptors stay outside the cell, while ligands of intracellular receptors (e.g. steroids) penetrate the membrane [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('16003c04-fce5-5d87-ade9-2727516e4b88', '65becf97-660c-5c08-a1d1-bb54384df5d9', 10);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('3c9c1ac9-69b4-5c3c-8091-f0ceb1468a5e', 'short', 'Compare signalling by hormones and by neurotransmitters.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3c9c1ac9-69b4-5c3c-8091-f0ceb1468a5e', 'Both are signalling chemicals that bind to specific receptors on target cells [1]; hormones travel in the blood to distant targets [1]; neurotransmitters diffuse across a synapse, acting locally and much faster [1].', 'Both are signalling chemicals that bind to specific receptors on target cells [1]; hormones travel in the blood to distant targets [1]; neurotransmitters diffuse across a synapse, acting locally and much faster [1].', '[{"text": "Marking point 1", "any": ["both bind"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["blood", "distant", "far"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["synapse", "local", "short distance", "fast"], "all": [], "marks": 1}]'::jsonb, 'Both are signalling chemicals that bind to specific receptors on target cells [1]; hormones travel in the blood to distant targets [1]; neurotransmitters diffuse across a synapse, acting locally and much faster [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('16003c04-fce5-5d87-ade9-2727516e4b88', '3c9c1ac9-69b4-5c3c-8091-f0ceb1468a5e', 11);
