insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3ddbf37d-fc86-58eb-9555-0eff62ee05bd', 'Insulin binds to a transmembrane receptor with tyrosine kinase activity [1]; this causes phosphorylation of tyrosine inside the cell, starting a sequence of reactions [1]; vesicles containing glucose transporters move to and fuse with the plasma membrane, increasing glucose uptake [1].', 'Insulin binds to a transmembrane receptor with tyrosine kinase activity [1]; this causes phosphorylation of tyrosine inside the cell, starting a sequence of reactions [1]; vesicles containing glucose transporters move to and fuse with the plasma membrane, increasing glucose uptake [1].', '[{"text": "Marking point 1", "any": ["receptor", "binds", "tyrosine kinase"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["phosphorylat", "tyrosine"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["vesicle", "glut4", "transporter", "glucose transporters"], "all": [], "marks": 1}]'::jsonb, 'Insulin binds to a transmembrane receptor with tyrosine kinase activity [1]; this causes phosphorylation of tyrosine inside the cell, starting a sequence of reactions [1]; vesicles containing glucose transporters move to and fuse with the plasma membrane, increasing glucose uptake [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
