insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0211c0ac-d49d-5d1c-9b92-be670f7c4e30', 'When the membrane reaches threshold, voltage-gated Na⁺ channels open and an action potential follows [1]; if threshold is not reached, no action potential occurs (all-or-nothing) [1].', 'When the membrane reaches threshold, voltage-gated Na⁺ channels open and an action potential follows [1]; if threshold is not reached, no action potential occurs (all-or-nothing) [1].', '[{"text": "Marking point 1", "any": ["voltage-gated sodium", "na channels open"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["all or nothing", "no action potential", "below threshold"], "all": [], "marks": 1}]'::jsonb, 'When the membrane reaches threshold, voltage-gated Na⁺ channels open and an action potential follows [1]; if threshold is not reached, no action potential occurs (all-or-nothing) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
