insert into public.questions (id, kind, prompt, options, marks, image_url) values ('1d431947-a9ac-5274-a3f3-a11d268c0d6a', 'short', 'Distinguish between conscious and unconscious processes, with an example of each.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Human_brain_lateral_view_description.JPG?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1d431947-a9ac-5274-a3f3-a11d268c0d6a', 'Conscious processes are ones we are aware of and control, e.g. choosing to pick up a pen [1]; unconscious processes happen without awareness, e.g. a reflex or control of heart rate [1].', 'Conscious processes are ones we are aware of and control, e.g. choosing to pick up a pen [1]; unconscious processes happen without awareness, e.g. a reflex or control of heart rate [1].', '[{"text": "Marking point 1", "any": ["aware", "voluntary", "decide", "control"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["reflex", "heart", "breathing", "without awareness", "automatic", "involuntary"], "all": [], "marks": 1}]'::jsonb, 'Conscious processes are ones we are aware of and control, e.g. choosing to pick up a pen [1]; unconscious processes happen without awareness, e.g. a reflex or control of heart rate [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('7b9087dc-3846-543d-a0db-da3785567ca6', '1d431947-a9ac-5274-a3f3-a11d268c0d6a', 11);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('4042e846-b240-53c3-be3f-ea9269dddc27', 'short', 'Describe the structure of a nerve as seen in transverse section.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Optic_nerve_--_intermed_mag.jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('4042e846-b240-53c3-be3f-ea9269dddc27', 'A protective sheath of connective tissue surrounds the nerve [1]; inside are bundles of nerve fibres of sensory and motor neurons [1]; some fibres are myelinated and some unmyelinated [1].', 'A protective sheath of connective tissue surrounds the nerve [1]; inside are bundles of nerve fibres of sensory and motor neurons [1]; some fibres are myelinated and some unmyelinated [1].', '[{"text": "Marking point 1", "any": ["sheath", "connective tissue", "protective"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["bundle", "fibres", "axons"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["myelin"], "all": [], "marks": 1}]'::jsonb, 'A protective sheath of connective tissue surrounds the nerve [1]; inside are bundles of nerve fibres of sensory and motor neurons [1]; some fibres are myelinated and some unmyelinated [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
