insert into public.questions (id, kind, prompt, options, marks, image_url) values ('cbf7dc4d-4604-5a88-b083-c774f5ace571', 'short', 'Explain how heart rate is controlled when blood pressure falls.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('cbf7dc4d-4604-5a88-b083-c774f5ace571', 'Baroreceptors [1] in the aorta and carotid arteries detect the fall in pressure [1]; they send impulses to the medulla, which sends impulses to the heart to increase heart rate and stroke volume, raising pressure (negative feedback) [1].', 'Baroreceptors [1] in the aorta and carotid arteries detect the fall in pressure [1]; they send impulses to the medulla, which sends impulses to the heart to increase heart rate and stroke volume, raising pressure (negative feedback) [1].', '[{"text": "Marking point 1", "any": ["baroreceptor"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["aorta", "carotid"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["medulla", "brainstem"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["increase", "faster", "stroke volume"], "all": [], "marks": 1}]'::jsonb, 'Baroreceptors [1] in the aorta and carotid arteries detect the fall in pressure [1]; they send impulses to the medulla, which sends impulses to the heart to increase heart rate and stroke volume, raising pressure (negative feedback) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
