insert into public.questions (id, kind, prompt, options, marks, image_url) values ('3aff9871-9f5a-5066-9754-6902f0ec967f', 'short', 'Explain how auxin causes a shoot to bend towards light.', '[]'::jsonb, 4, 'https://commons.wikimedia.org/wiki/Special:FilePath/Phototropism_Diagram.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3aff9871-9f5a-5066-9754-6902f0ec967f', 'Auxin is moved to the shaded side of the shoot [1] by auxin efflux carriers positioned on that side of the cells [1]; auxin promotes H⁺ secretion into the cell walls, loosening cross-links between cellulose [1]; cells on the shaded side elongate more, so the shoot bends towards the light [1].', 'Auxin is moved to the shaded side of the shoot [1] by auxin efflux carriers positioned on that side of the cells [1]; auxin promotes H⁺ secretion into the cell walls, loosening cross-links between cellulose [1]; cells on the shaded side elongate more, so the shoot bends towards the light [1].', '[{"text": "Marking point 1", "any": ["shaded", "dark side", "away from the light"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["efflux", "carrier", "transport"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["hydrogen ion", "acid", "apoplast"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["elongat", "faster", "grow more"], "all": [], "marks": 1}]'::jsonb, 'Auxin is moved to the shaded side of the shoot [1] by auxin efflux carriers positioned on that side of the cells [1]; auxin promotes H⁺ secretion into the cell walls, loosening cross-links between cellulose [1]; cells on the shaded side elongate more, so the shoot bends towards the light [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('7b9087dc-3846-543d-a0db-da3785567ca6', '3aff9871-9f5a-5066-9754-6902f0ec967f', 27);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('240a1833-764c-58d4-aae9-b0094c053599', 'short', 'Explain the benefit of positive feedback in fruit ripening.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('240a1833-764c-58d4-aae9-b0094c053599', 'Ethylene stimulates ripening [1]; ripening fruit produce more ethylene, which speeds ripening further (positive feedback) [1]; so fruits ripen rapidly and at the same time, attracting animals to disperse seeds [1].', 'Ethylene stimulates ripening [1]; ripening fruit produce more ethylene, which speeds ripening further (positive feedback) [1]; so fruits ripen rapidly and at the same time, attracting animals to disperse seeds [1].', '[{"text": "Marking point 1", "any": ["ethylene", "ethene"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["more ethylene", "stimulates production", "positive feedback", "increases"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["rapid", "synchron", "same time", "together"], "all": [], "marks": 1}]'::jsonb, 'Ethylene stimulates ripening [1]; ripening fruit produce more ethylene, which speeds ripening further (positive feedback) [1]; so fruits ripen rapidly and at the same time, attracting animals to disperse seeds [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('7b9087dc-3846-543d-a0db-da3785567ca6', '240a1833-764c-58d4-aae9-b0094c053599', 28);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('d74d78fd-49aa-588e-90fc-76317221e351', 'short', 'Outline how you would investigate the effect of light from one side on the growth of seedlings.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d74d78fd-49aa-588e-90fc-76317221e351', 'Grow seedlings in a box with light entering from one side only, with a control group in uniform light [1]; measure the angle of curvature after a set time with a protractor/image analysis [1]; keep species, age, temperature and water the same and use many seedlings to calculate a mean [1].', 'Grow seedlings in a box with light entering from one side only, with a control group in uniform light [1]; measure the angle of curvature after a set time with a protractor/image analysis [1]; keep species, age, temperature and water the same and use many seedlings to calculate a mean [1].', '[{"text": "Marking point 1", "any": ["one side", "unilateral", "lamp", "box with a hole"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["angle", "curvature", "protractor", "measure"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["control", "same", "repeat", "several"], "all": [], "marks": 1}]'::jsonb, 'Grow seedlings in a box with light entering from one side only, with a control group in uniform light [1]; measure the angle of curvature after a set time with a protractor/image analysis [1]; keep species, age, temperature and water the same and use many seedlings to calculate a mean [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
